<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // @GeneratedValue(strategy = GenerationType.IDENTITY)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // Exercise 1</span></span>
